using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddSingleton<NoteService>();

builder.Services.AddChatClient(chatBuilder => chatBuilder
    .UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18",
        new OpenAIClient(
            builder.Configuration["AI:ApiKey"]
                ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
                ?? throw new InvalidOperationException(
                    "Set AI:ApiKey in configuration or the OPENAI_API_KEY environment variable."))));

using var app = builder.Build();

var chatClient = app.Services.GetRequiredService<IChatClient>();
var noteService = app.Services.GetRequiredService<NoteService>();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            return WebSearchTool.SearchAsync(query);
        },
        "web_search",
        "Searches the web for information on a topic. Returns a list of results with titles, snippets, and URLs."),

    AIFunctionFactory.Create(
        ([Description("Title or label for the note")] string title,
         [Description("Content of the note")] string content) =>
        {
            noteService.AddNote(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = noteService.GetAllNotes();
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", notes.Select((n, i) => $"[{i + 1}] {n.Title}\n{n.Content}"));
        },
        "get_notes",
        "Retrieves all previously saved research notes."),
};

var agent = new ChatClientAgent(chatClient, tools)
{
    Name = "ResearchAgent",
    Instructions = """
        You are a research agent. When given a topic, you:
        1. Search the web for relevant information using the web_search tool (perform 2-3 searches with varied queries).
        2. Save key findings as notes using the save_note tool.
        3. After gathering enough information, retrieve your notes with get_notes.
        4. Produce a well-structured summary with key findings and source URLs.
        Be thorough but concise. Always cite sources.
        """,
};

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

// --- Supporting types ---

public sealed class NoteService
{
    private readonly List<Note> _notes = [];

    public void AddNote(string title, string content) =>
        _notes.Add(new Note(title, content, DateTime.UtcNow));

    public IReadOnlyList<Note> GetAllNotes() => _notes;
}

public sealed record Note(string Title, string Content, DateTime CreatedAt);

public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "application/json" },
        },
    };

    public static async Task<string> SearchAsync(string query)
    {
        // Uses the free DuckDuckGo instant-answer API as a default.
        // Swap with Bing/Google API by setting AI:SearchEndpoint.
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await HttpClient.GetStringAsync(url);

            // Parse key fields from the DDG response
            using var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract (main answer)
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrEmpty(abstractText))
            {
                results.Add($"**{root.GetProperty("Heading").GetString()}**\n{abstractText}\nSource: {abstractUrl}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) &&
                        topic.TryGetProperty("FirstURL", out var topicUrl))
                    {
                        results.Add($"- {text.GetString()}\n  URL: {topicUrl.GetString()}");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for \"{query}\". Try a more specific search.";
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }
}

